try:
    import pandas as _pd
    _orig_get_loc = _pd.Index.get_loc
    _VALID = (None, "pad", "ffill", "backfill", "bfill", "nearest")

    def _get_loc_compat(self, key, method=None, tolerance=None):
        if method not in _VALID:
            raise ValueError(
                "Invalid fill method. Expecting pad (ffill), backfill (bfill) or nearest."
            )
        if method is None and tolerance is None:
            return _orig_get_loc(self, key)
        indexer = self.get_indexer([key], method=method, tolerance=tolerance)
        if getattr(indexer, "ndim", 1) and indexer.size == 1:
            idx = indexer[0]
            if idx < 0:
                raise KeyError(key)
            return idx
        return indexer

    _pd.Index.get_loc = _get_loc_compat
